class AdditionalServicesDialogController{constructor($mdDialog,$http,jobId,clientId){this._$mdDialog=$mdDialog;this._$http=$http;this.selected=[];this.isLoading=false;this.query={order:"name",limit:5,page:1};this.allJobAdditionalServices=[];this.allClientAdditionalServices=[];this.tableList=[];this._getAdditionalServicesForJob(jobId).then(services=>{this.allJobAdditionalServices=services;this.updateTable()});this._getAllAdditionalServicesForClient(clientId).then(allClientServices=>{this.allClientAdditionalServices=allClientServices})}async _getAdditionalServicesForJob(jobId){const url="job/GetClientItemsForSingleJob/";const response=await this._$http.get(`${url}?jobId=${jobId}`);return response.data}async _getAllAdditionalServicesForClient(clientId){const url="job/GetAllClientItems/";const response=await this._$http.get(`${url}?clientId=${clientId}`);return response.data}updateTable(){const jobServices=this.allJobAdditionalServices;const query=this.query;jobServices.sort((a,b)=>a[query.order]>b[query.order]?1:-1);const startIndex=(query.page-1)*query.limit;const endIndex=startIndex+query.limit;this.tableList=jobServices.slice(startIndex,endIndex)}async addService(){}async bookServices(allJobServices){}cancel(){this._$mdDialog.cancel()}}